// Form label -> API model name. 1080p is only offered on the standard tier.
const MODELS = {
  'Seedance 2.0 Mini (lowest cost)': 'seedance-2.0-mini',
  'Seedance 2.0 Fast': 'seedance-2.0-fast',
  'Seedance 2.0 (best quality, up to 1080p)': 'seedance-2.0',
};

const form = $('Video request form').first().json;
const model = MODELS[form['Model']] ?? 'seedance-2.0-mini';
let resolution = form['Resolution'];
if (resolution === '1080p' && model !== 'seedance-2.0') resolution = '720p';

const body = {
  model,
  prompt: form['What should happen in the video'],
  resolution,
  duration: Number(form['Length (seconds)']),
  aspect_ratio: form['Aspect ratio'],
};

if ($('Upload photo to apimodels').isExecuted) {
  body.first_frame_url = $('Upload photo to apimodels').first().json.data.publicUrl;
}

return [{ json: { body } }];

